//
// This is only a SKELETON file for the 'List Ops' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export class List {
  constructor(values = []) {
    this.values = values;
  }

  append(other) {
    return new List([...this.values, ...other.values]);
  }

  concat(other) {
    const result = [...this.values];
    for (const item of other.values) {
      if (item instanceof List) {
        result.push(...item.values);
      } else {
        result.push(item);
      }
    }
    return new List(result);
  }

  filter(predicate) {
    const result = [];
    for (const item of this.values) {
      if (predicate(item)) {
        result.push(item);
      }
    }
    return new List(result);
  }

  map(fn) {
    const result = [];
    for (const item of this.values) {
      result.push(fn(item));
    }
    return new List(result);
  }

  length() {
    let count = 0;
    for (const _ of this.values) {
      count += 1;
    }
    return count;
  }

  foldl(fn, acc) {
    for (const item of this.values) {
      acc = fn(acc, item);
    }
    return acc;
  }

  foldr(fn, acc) {
    for (let i = this.values.length - 1; i >= 0; i -= 1) {
      acc = fn(acc, this.values[i]);
    }
    return acc;
  }

  reverse() {
    const result = [];
    for (let i = this.values.length - 1; i >= 0; i -= 1) {
      result.push(this.values[i]);
    }
    return new List(result);
  }
}

